		diff := el - minEL
		if diff > 0 {
			penalty := float64(diff) * 0.008
			if penalty > 0.05 {
				penalty = 0.05
			}
			scores[snap.ID] -= penalty
		}
	}

	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

